                end
            elseif key == "rewards" then
                for ti = 1, #value do
                    table.insert(self.rewards, { goodsId = value[ti].goodsId, num = value[ti].num})
                end
            elseif key == "endTime" then
                self[key] = value
                self.nextRefreshLeftSeconds = value
            elseif key == "nextRefreshLeftSeconds" then
                if self.nextRefreshLeftSeconds == 0 then
                    self.nextRefreshLeftSeconds = value
